files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background-color: #1e1e2f;
  background-image: linear-gradient(45deg, #1e1e2f 25%, #2a2a40 25%, #2a2a40 50%, #1e1e2f 50%, #1e1e2f 75%, #2a2a40 75%, #2a2a40);
  background-size: 40px 40px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  color: #e0e0e0;
}

.card {
  background-color: #2a2a40;
  border: 4px solid #5a5a7a;
  border-radius: 12px;
  padding: 2rem 1.5rem;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 0 #0f0f1a;
}

.title {
  font-size: 1.75rem;
  margin-bottom: 1.5rem;
  color: #f0c040;
  text-shadow: 2px 2px 0 #0f0f1a;
  letter-spacing: 2px;
}

.question {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  font-weight: 600;
  min-height: 2.5rem;
}

.answers {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.answer {
  background-color: #3a3a5a;
  border: 3px solid #5a5a7a;
  border-radius: 8px;
  color: #e0e0e0;
  font-size: 1.25rem;
  font-weight: bold;
  padding: 0.75rem 1.5rem;
  cursor: pointer;
  flex: 1;
  transition: background-color 0.1s, transform 0.1s, border-color 0.1s;
  box-shadow: 0 4px 0 #0f0f1a;
}

.answer:hover:not(:disabled) {
  background-color: #4a4a6a;
  border-color: #7a7a9a;
}

.answer:active:not(:disabled) {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #0f0f1a;
}

.answer:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
}

.answer:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.score {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  color: #f0c040;
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

.control {
  background-color: #5a5a7a;
  border: 3px solid #7a7a9a;
  border-radius: 8px;
  color: #e0e0e0;
  font-size: 1rem;
  font-weight: bold;
  padding: 0.6rem 1.2rem;
  cursor: pointer;
  transition: background-color 0.1s, transform 0.1s;
  box-shadow: 0 4px 0 #0f0f1a;
}

.control:hover {
  background-color: #6a6a8a;
}

.control:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #0f0f1a;
}

.control:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  .answers {
    flex-direction: column;
    gap: 0.75rem;
  }
  .answer {
    padding: 0.6rem 1rem;
  }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let score = 0;
let currentQuestion = 0;
let answered = false;

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

function updateScore() {
  scoreEl.textContent = `Score: ${score}`;
}

function lockAnswers(lock) {
  answerA.disabled = lock;
  answerB.disabled = lock;
}

function loadQuestion(index) {
  const q = questions[index];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answered = false;
  lockAnswers(false);
}

function handleAnswer(choice) {
  if (answered) return;
  answered = true;
  lockAnswers(true);
  const q = questions[currentQuestion];
  if (choice === q.correct) {
    score++;
    updateScore();
  }
}

function next() {
  if (!answered) return;
  if (currentQuestion === 0) {
    currentQuestion = 1;
    loadQuestion(currentQuestion);
  } else if (currentQuestion === 1) {
    questionEl.textContent = 'Finished';
    lockAnswers(true);
  }
}

function restart() {
  score = 0;
  currentQuestion = 0;
  updateScore();
  loadQuestion(0);
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));
nextBtn.addEventListener('click', next);
restartBtn.addEventListener('click', restart);

updateScore();
loadQuestion(0);
